(()=>{const screen=document.getElementById('intro-screen');if(!screen)return;const skip=document.getElementById('skip-intro');const replay=document.getElementById('replay-intro');const status=document.getElementById('intro-status');const meter=document.getElementById('intro-meter-fill');const command=document.getElementById('intro-command');const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');let timers=[];let returningFocus=null;let finishing=false;const later=(fn,ms)=>{const t=setTimeout(fn,ms);timers.push(t);return t};const clear=()=>{timers.forEach(clearTimeout);timers=[]};function complete(immediate=false){if(!screen.open||finishing)return;finishing=true;clear();try{sessionStorage.setItem('fouad-intro-seen','yes')}catch{}const close=()=>{screen.close();screen.classList.remove('is-leaving');finishing=false;if(returningFocus&&returningFocus.isConnected)returningFocus.focus();else document.getElementById('main')?.focus({preventScroll:true})};if(immediate||reduced.matches)close();else{screen.classList.add('is-leaving');later(close,660)}}function start(manual=false){if(screen.open)return;clear();returningFocus=manual?document.activeElement:null;finishing=false;screen.classList.remove('is-leaving');status.textContent='Opening the field notes…';command.textContent='open portfolio';meter.style.width='8%';document.querySelectorAll('.intro-steps span').forEach(x=>x.classList.remove('active'));screen.showModal();skip.focus();if(reduced.matches){status.textContent='Welcome to my corner of the internet.';meter.style.width='100%';later(()=>complete(true),350);return}later(()=>{meter.style.width='35%';document.getElementById('intro-step-one').classList.add('active');command.textContent='load field_notes';status.textContent='A few projects. A lot of curiosity.'},300);later(()=>{meter.style.width='72%';document.getElementById('intro-step-two').classList.add('active');command.textContent='start fouadOS';status.textContent='Getting the little desktop ready…'},800);later(()=>{meter.style.width='100%';document.getElementById('intro-step-three').classList.add('active');command.textContent='welcome, visitor';status.textContent='Make yourself at home.'},1250);later(()=>complete(),1650);later(()=>complete(true),3500)}skip.addEventListener('click',()=>complete(true));screen.addEventListener('cancel',e=>{e.preventDefault();complete(true)});replay.addEventListener('click',()=>start(true));let seen=false;try{seen=sessionStorage.getItem('fouad-intro-seen')==='yes'}catch{}if(!seen)start();})();
